options(stringsAsFactors=FALSE)
b<-'.';o<-file.path(b,'EHP_R2_20261118');p<-file.path(o,'Source_data')
.libPaths(c(file.path(b,'TB_metabolome_exposome_20261115_2130/analysis_MWAS_ExWAS/Rlib'),.libPaths()));library(ggplot2);library(patchwork);library(cowplot)
blue<-'#0072B2';orange<-'#D55E00';grey<-'#A5ADB4';ink<-'#263746'
cowplot::set_null_device(function(width,height)svglite::svglite(tempfile(fileext='.svg'),width=width,height=height))
theme_set(theme_classic(base_family='Arial',base_size=7)+theme(plot.margin=margin(4,6,4,4),legend.position='bottom'))
savefig<-function(fig,name,w,h){for(ex in c('svg','pdf','png'))ggsave(file.path(o,'Figures',paste0(name,'.',ex)),fig,width=w,height=h,dpi=600,bg='white',device=if(ex=='pdf')function(filename,width,height,...)quartz(type='pdf',file=filename,width=width,height=height,family='Arial')else ex);ggsave(file.path(o,'Figures',paste0(name,'_preview.png')),fig,width=w,height=h,dpi=200,bg='white')}
arc<-function(a1,a2,r1,r2,id){aa<-seq(a1,a2,length.out=max(7,ceiling(abs(a1-a2)*90)));data.frame(x=c(r1*cos(aa),r2*cos(rev(aa))),y=c(r1*sin(aa),r2*sin(rev(aa))),id=id)}
colour<-function(v,m)scales::col_numeric(c(blue,'white',orange),domain=c(-m,m))(v)
# Figure 2: linked angular columns, complete exposure screen and all 34 lipid tracks.
x<-read.csv(file.path(o,'B_results/primary188.csv'));r<-read.csv(file.path(p,'05_full_spectrum_primary_6392.csv'));family<-sort(unique(x$family));x<-x[order(match(x$family,family),x$variable),];x$i<-seq_len(nrow(x));x$a<-pi/2-2*pi*(x$i-.5)/188
v<-read.csv(file.path(b,'IJHEH_Exposure_Nutrition_Phenotype_20261118/Source_data/Figure2_track_key_34.csv'))$variable;stopifnot(length(v)==34,nrow(r)==6392,nrow(x)==188)
r$i<-match(r$variable,x$variable);r$track<-match(r$metabolite,v);r$a<-x$a[r$i];r$rad<-2.05+.080*(r$track-.5);stopifnot(all(!is.na(r$i)),all(!is.na(r$track)))
r$col<-colour(ifelse(r$status=='ok',asinh(r$beta/.1),NA),asinh(1.7/.1));r$col[r$status!='ok']<-'#D0D0D0';stopifnot(max(abs(r$beta[r$status=='ok']))<1.7)
inner<-do.call(rbind,lapply(seq_len(nrow(r)),function(j){z<-arc(pi/2-2*pi*(r$i[j]-1)/188,pi/2-2*pi*r$i[j]/188,2.05+.080*(r$track[j]-1),2.05+.080*r$track[j],j);z$col<-r$col[j];z}))
x$col<-colour(sign(x$b)*(-log10(x$q_188)),2.4);x$col[x$status=='unstable']<-'#888888';x$col[x$status!='ok'&x$status!='unstable']<-'#D3D3D3';outer<-do.call(rbind,lapply(1:188,function(j){z<-arc(pi/2-2*pi*(j-1)/188,pi/2-2*pi*j/188,4.9,5.16,j);z$col<-x$col[j];z}))
bands<-nodes<-branches<-list()
for(j in seq_along(family)){ii<-which(x$family==family[j]);aa<-pi/2-2*pi*c(min(ii)-1,max(ii))/188;am<-mean(aa);z<-arc(aa[1],aa[2],5.22,5.36,j);z$col<-if(j%%2)'#D8E4E9'else'#E2E4E6';bands[[j]]<-z;nodes[[j]]<-data.frame(family=family[j],x=1.2*cos(am),y=1.2*sin(am),lx=5.61*cos(am),ly=5.61*sin(am),id=sprintf('%02d',j),n=length(ii));branches[[j]]<-data.frame(x=1.2*cos(am),y=1.2*sin(am),xe=2*cos(x$a[ii]),ye=2*sin(x$a[ii]))}
bands<-do.call(rbind,bands);nodes<-do.call(rbind,nodes);branches<-do.call(rbind,branches)
pc<-ggplot()+geom_segment(data=nodes,aes(x=0,y=0,xend=x,yend=y),colour='#ABB8C1',linewidth=.3)+geom_segment(data=branches,aes(x,y,xend=xe,yend=ye),colour='#D5DDE2',linewidth=.18)+geom_point(data=nodes,aes(x,y),colour='#929CA5',size=.65)+geom_polygon(data=inner,aes(x,y,group=id,fill=col))+geom_polygon(data=outer,aes(x,y,group=id,fill=col),colour='white',linewidth=.08)+geom_polygon(data=bands,aes(x,y,group=id,fill=col),colour='white',linewidth=.2)+scale_fill_identity()+geom_point(data=subset(r,status=='ok'&q_global<.05),aes(rad*cos(a),rad*sin(a)),size=.24,colour='#15232D')+geom_text(data=subset(x,status=='ok'&q_188<.05),aes(5.03*cos(a),5.03*sin(a)),label='*',size=3)+geom_text(data=nodes,aes(lx,ly,label=id),size=2.1,colour=ink)+annotate('label',x=0,y=0,label='188 biomarkers\n20 families\n34 lipid traits',size=2.7,lineheight=1.25,fill='white',colour=ink,linewidth=0)+coord_equal(xlim=c(-5.95,5.95),ylim=c(-5.95,5.95),expand=FALSE,clip='off')+theme_void(base_family='Arial')+theme(plot.margin=margin(3,3,3,3))
key<-function(vv,m,lab,at){d<-data.frame(z=seq(-m,m,length.out=180));d$col<-colour(d$z,m);ggplot(d,aes(z,0,fill=col))+geom_tile(height=.5)+scale_fill_identity()+scale_x_continuous(breaks=vv,labels=at,expand=c(0,0))+labs(x=lab,y=NULL)+theme_classic(base_family='Arial',base_size=6)+theme(axis.text.y=element_blank(),axis.ticks.y=element_blank(),axis.line=element_blank(),axis.title.x=element_text(size=6.4),plot.margin=margin(0,12,0,12))}
keys<-key(c(-2.4,0,2.4),2.4,'Outer ring: signed −log10(q188)',c('−2.4','0','2.4'))|key(asinh(c(-1,-.1,0,.1,1)/.1),asinh(1.7/.1),'Lipid tracks: coefficient (asinh scale)',c('−1','−.1','0','.1','1'))
short<-c('Arsenic species (urine)'='Arsenic, urine','Caffeine metabolites'='Caffeine metabolites','Chlorophenols (pesticide-related, urine)'='Chlorophenols','DEET metabolites (urine)'='DEET metabolites','Essential trace elements (serum)'='Essential elements, serum','Iodine (urine)'='Iodine, urine','Mercury species (blood)'='Mercury species, blood','Metals (blood)'='Metals, blood','Metals (urine)'='Metals, urine','Organophosphate flame-retardant metabolites (urine)'='OP flame retardants','Organophosphate pesticide metabolites (urine)'='OP pesticides','PAH metabolites (urine)'='PAH metabolites','PFAS (serum)'='PFAS','Perchlorate/nitrate/thiocyanate (urine)'='Perchlorate / nitrate / SCN','Phenols and parabens (urine)'='Phenols / parabens','Phthalate/plasticizer metabolites (urine)'='Phthalates / plasticizers','Pyrethroid/herbicide/OP metabolites (urine)'='Pyrethroid / herbicide / OP','Tobacco smoke biomarkers'='Tobacco biomarkers','VOC metabolites (urine)'='VOC metabolites, urine','VOCs (blood)'='VOCs, blood')[family];stopifnot(!anyNA(short));legend<-ggdraw()
for(j in seq_along(family)){co<-(j-1)%/%7;rr<-(j-1)%%7;legend<-legend+draw_label(sprintf('%02d %s (%d)',j,short[j],nodes$n[j]),x=.006+co*.333,y=.95-rr*.137,hjust=0,size=6.1,fontfamily='Arial')}
tk<-ggdraw();for(j in 1:34){co<-(j-1)%/%7;rr<-(j-1)%%7;tk<-tk+draw_label(paste0(j,': ',sub('^LBX','',sub('^fa_','',v[j]))),x=.01+co*.20,y=.95-rr*.14,hjust=0,size=5.7,fontfamily='Arial')}
hits<-subset(x,status=="ok"&q_188<.05); hits<-hits[match(c("LBXBCD","LBX2DF","LBXVFN"),hits$variable),]; hits$name<-c("Blood cadmium","2,5-Dimethylfuran","Furan");hits$unit<-c("doubling","detected vs <LOD","detected vs <LOD"); cap<-ggdraw();for(i in 1:3){cap<-cap+draw_label(sprintf("%s  |  %s  |  OR %.3f (%.3f to %.3f)",hits$name[i],hits$unit[i],hits$OR[i],hits$low[i],hits$high[i]),x=.08,y=1.05-.30*i,hjust=0,size=7)}
hits$abbr<-c("Cd","2,5-DMF","Furan")
hits$ex<-6.06*cos(hits$a);hits$ey<-6.06*sin(hits$a);hits$ey[2]<-hits$ey[2]-.19;hits$ey[3]<-hits$ey[3]+.15
pc<-pc+geom_segment(data=hits,aes(x=5.05*cos(a),y=5.05*sin(a),xend=ex,yend=ey),linewidth=.25,colour=ink)+geom_label(data=hits,aes(ex,ey,label=abbr),size=2.25,label.padding=unit(.06,"lines"),linewidth=0)+coord_equal(xlim=c(-6.65,6.65),ylim=c(-6.5,6.5),clip="off")
fig2<-pc/keys/cap/legend/tk+plot_layout(heights=c(7.2,.48,.64,1.05,.8));savefig(fig2,"Figure2_full_exposome_circular",7.2,10.17)
